/* Contact form (Core shortcode) */
.wpe-contact-form label { display: block; font-size: 13px; font-weight: 600; margin: 14px 0 6px; }
.wpe-contact-form input, .wpe-contact-form select, .wpe-contact-form textarea { width: 100%; border: 1px solid transparent; border-radius: 10px; background: var(--wp--preset--color--surface-alt); padding: 12px 14px; font: inherit; color: var(--wp--preset--color--text); }
.wpe-contact-form input:focus, .wpe-contact-form select:focus, .wpe-contact-form textarea:focus { outline: 0; border-color: var(--wp--preset--color--secondary); }
.wpe-contact-form button { margin-top: 18px; width: 100%; border: 0; border-radius: 999px; padding: 14px; background: var(--wp--preset--color--primary); color: var(--wp--preset--color--ink); font-weight: 700; cursor: pointer; }
.wpe-contact-form .wpe-contact-form__note { font-size: 12px; color: var(--wp--preset--color--text-muted); margin-top: 12px; }
.wpe-contact-form .wpe-contact-form__hp { position: absolute; left: -9999px; }
.wpe-contact-notice { padding: 12px 16px; border-radius: 10px; background: rgba(22, 163, 74, .1); color: #166534; font-size: 14px; }
.wpe-contact-notice.is-error { background: rgba(220, 38, 38, .08); color: #991b1b; }

/* Section rhythm: plain sections that follow plain sections share the gap. */
.wpe-ess-section:not(.wpe-ess-section--alt):not(.wpe-ess-section--ink):not(.wpe-ess-section--pull) + .wpe-ess-section:not(.wpe-ess-section--alt):not(.wpe-ess-section--ink) { padding-top: 0; }
.wpe-ess-section > .wpe-ess-h2 { max-width: none; margin-inline: 0 !important; }

.wpe-ess-page-hero:not(.wpe-ess-page-hero--dark) > .wpe-ess-page__title, .wpe-ess-page-hero:not(.wpe-ess-page-hero--dark) > .wpe-ess-lead { max-width: 1200px; }
.wpe-ess-page-hero:not(.wpe-ess-page-hero--dark) > .wpe-ess-hero__search--light { max-width: 1200px; }
.wpe-ess-page-hero:not(.wpe-ess-page-hero--dark) > .wpe-ess-hero__search--light :is(.wp-block-search__inside-wrapper, .wpe-search__row) { max-width: 420px; }
.wpe-ess-card.wpe-ess-contact { flex-direction: row; align-items: center; gap: 16px; }
.wpe-contact-form input, .wpe-contact-form select, .wpe-contact-form textarea { box-sizing: border-box; }

/* Header (Figma) */
.wpe-ess-logo { display: inline-flex; align-items: center; gap: 10px; text-decoration: none; color: var(--wp--preset--color--text); }
.wpe-ess-logo__mark { position: relative; font-family: var(--wp--preset--font-family--heading); font-weight: 800; font-size: 30px; line-height: 1; color: #2F6BE0; letter-spacing: -0.04em; }
.wpe-ess-logo__mark i { position: absolute; right: -7px; bottom: 3px; width: 7px; height: 7px; border-radius: 50%; background: var(--wp--preset--color--primary); }
.wpe-ess-logo__text { display: flex; flex-direction: column; line-height: 1.05; }
.wpe-ess-logo__text b { font-family: var(--wp--preset--font-family--heading); font-size: 21px; letter-spacing: -0.02em; }
.wpe-ess-logo__text small { font-family: var(--wp--preset--font-family--mono); font-size: 7px; letter-spacing: .12em; text-transform: uppercase; color: var(--wp--preset--color--text-muted); }
.wpe-ess-actions { gap: 10px !important; align-items: center; }
.wpe-ess-signin { margin: 0; font-size: 14px; font-weight: 600; }
.wpe-ess-signin a { color: var(--wp--preset--color--text); text-decoration: none; }
.wpe-ess-header :is(.wp-block-search__button, .wpe-search__submit) { width: 38px; height: 38px; border-radius: 50%; background: var(--wp--preset--color--surface-alt) !important; }
.wpe-ess-header .wp-block-navigation-item__content { padding: 8px 14px; border-radius: 999px; font-size: 15px; }
.wpe-ess-header .current-menu-item > .wp-block-navigation-item__content, .wpe-ess-header .wp-block-navigation-item__content:hover { background: var(--wp--preset--color--surface-alt); }
.wpe-ess-footer .wpe-ess-logo, .wpe-ess-footer .wpe-ess-logo__text small { color: #fff; }
@media (max-width: 1100px) { .wpe-ess-signin { display: none; } }
@media (max-width: 781px) { .wpe-ess-logo__text small { display: none; } }

/* Navy header on pages that open with a navy hero (Figma 01 Home, 08 Docs) */
body:has(.wpe-ess-hero, .wpe-ess-page-hero--docs) .wpe-ess-header { background: #0b1a3d; border-bottom: 1px solid rgba(255,255,255,.08); }
